export interface ConnectorConfig {
  openaiApiKey: string
  openaiModel?: string
  fetch?: typeof fetch
}

export interface GitHubPullRequestPayload {
  action: string
  pull_request: {
    title: string
    body: string
    user: {
      login: string
    }
    head: {
      sha: string
    }
  }
}

export interface OpenAIResponse {
  id: string
  object: string
  created: number
  model: string
  choices: Array<{
    index: number
    message: {
      role: string
      content: string
    }
    finish_reason: string
  }>
  usage: {
    prompt_tokens: number
    completion_tokens: number
    total_tokens: number
  }
}

export interface PRAnalysis {
  summary: string
  risks: string[]
  suggestedReviewers: string[]
}

export interface HandleResult {
  openaiResponseId: string
  analysis: PRAnalysis
}

const OPENAI_URL = 'https://api.openai/v1/chat/completions'
const DEFAULT_MODEL = 'gpt-4o-mini'

const RESPONSE_SCHEMA = {
  type: 'json_schema',
  json_schema: {
    name: 'pr_analysis',
    strict: true,
    schema: {
      type: 'object',
      properties: {
        summary: { type: 'string' },
        risks: { type: 'array', items: { type: 'string' } },
        suggestedReviewers: { type: 'array', items: { type: 'string' } }
      },
      required: ['summary', 'risks', 'suggestedReviewers'],
      additionalProperties: false
    }
  }
}

function validatePayload(payload: unknown): asserts payload is GitHubPullRequestPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (p.action !== 'opened') {
    throw new Error(`Expected action "opened", got "${p.action}"`)
  }
  if (!p.pull_request || typeof p.pull_request !== 'object') {
    throw new Error('Missing pull_request object')
  }
  const pr = p.pull_request as Record<string, unknown>
  if (typeof pr.title !== 'string' || !pr.title.trim()) {
    throw new Error('pull_request.title is required and must be a non-empty string')
  }
  if (typeof pr.body !== 'string') {
    throw new Error('pull_request.body is required and must be a string')
  }
  if (!pr.user || typeof pr.user !== 'object' || typeof (pr.user as Record<string, unknown>).login !== 'string') {
    throw new Error('pull_request.user.login is required and must be a string')
  }
  if (!pr.head || typeof pr.head !== 'object' || typeof (pr.head as Record<string, unknown>).sha !== 'string') {
    throw new Error('pull_request.head.sha is required and must be a string')
  }
}

function buildPrompt(pr: GitHubPullRequestPayload['pull_request']): string {
  return `Analyze this pull request:\n\nTitle: ${pr.title}\n\nBody: ${pr.body}\n\nAuthor: ${pr.user.login}\n\nCommit SHA: ${pr.head.sha}\n\nProvide a structured analysis with summary, risks, and suggested reviewers.`
}

async function callOpenAI(
  apiKey: string,
  model: string,
  prompt: string,
  fetchFn: typeof fetch
): Promise<OpenAIResponse> {
  const body = {
    model,
    messages: [{ role: 'user' as const, content: prompt }],
    response_format: RESPONSE_SCHEMA
  }

  const response = await fetchFn(OPENAI_URL, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    throw new Error(`OpenAI API error: ${response.status} ${response.statusText} for ${OPENAI_URL}`)
  }

  return response.json() as Promise<OpenAIResponse>
}

function parseAnalysis(content: string): PRAnalysis {
  try {
    const parsed = JSON.parse(content) as PRAnalysis
    if (
      typeof parsed.summary !== 'string' ||
      !Array.isArray(parsed.risks) ||
      !Array.isArray(parsed.suggestedReviewers)
    ) {
      throw new Error('Invalid analysis structure')
    }
    return parsed
  } catch (e) {
    throw new Error(`Failed to parse OpenAI response content: ${e instanceof Error ? e.message : String(e)}`)
  }
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const pr = payload as GitHubPullRequestPayload

  const prompt = buildPrompt(pr.pull_request)
  const model = config.openaiModel ?? DEFAULT_MODEL
  const fetchFn = config.fetch ?? fetch

  const openaiResponse = await callOpenAI(config.openaiApiKey, model, prompt, fetchFn)

  const content = openaiResponse.choices[0]?.message?.content
  if (!content) {
    throw new Error('OpenAI response missing message content')
  }

  const analysis = parseAnalysis(content)

  return {
    openaiResponseId: openaiResponse.id,
    analysis
  }
}

import { describe, it, expect, vi } from 'vitest'
import { handle, ConnectorConfig, GitHubPullRequestPayload, HandleResult } from './connector'
import {
  SOURCE_EXAMPLE,
  TARGET_ENDPOINTS,
  contractFetch,
  fakeFetch,
  jsonResponse,
  RecordedCall
} from './fixtures'

describe('contract', () => {
  it('handles the documented example payload', async () => {
    const { fetch, calls } = contractFetch()
    const config: ConnectorConfig = {
      openaiApiKey: 'test-key',
      fetch
    }
    const result = await handle(SOURCE_EXAMPLE as unknown as GitHubPullRequestPayload, config)
    expect(calls.length).toBeGreaterThan(0)
    expect(result.openaiResponseId).toBe('chatcmpl-123')
    expect(result.analysis.summary).toContain('new feature')
    expect(result.analysis.risks).toHaveLength(2)
    expect(result.analysis.suggestedReviewers).toHaveLength(2)
  })
})

describe('handle', () => {
  it('sends correct request body to OpenAI with all mapped fields', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      expect(req.method).toBe('POST')
      expect(req.url).toBe('https://api.openai/v1/chat/completions')
      expect(req.headers.get('authorization')).toBe('Bearer test-key')
      expect(req.headers.get('content-type')).toBe('application/json')
      const body = req.json as Record<string, unknown>
      expect(body.model).toBe('gpt-4o-mini')
      expect(body.messages).toHaveLength(1)
      expect(body.messages[0].role).toBe('user')
      const content = body.messages[0].content as string
      expect(content).toContain('Title: Add new feature')
      expect(content).toContain('Body: This PR adds a new feature')
      expect(content).toContain('Author: octocat')
      expect(content).toContain('Commit SHA: a1b2c3d4e5f6789012345678901234567890abcd')
      expect(body.response_format).toBeDefined()
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const config: ConnectorConfig = { openaiApiKey: 'test-key', fetch }
    const result = await handle(SOURCE_EXAMPLE as unknown as GitHubPullRequestPayload, config)

    expect(result.openaiResponseId).toBe('chatcmpl-123')
    expect(calls).toHaveLength(1)
  })

  it('uses custom model from config', async () => {
    const { fetch, calls } = fakeFetch((req) => {
      const body = req.json as Record<string, unknown>
      expect(body.model).toBe('gpt-4')
      return jsonResponse(TARGET_ENDPOINTS[0].response)
    })

    const config: ConnectorConfig = { openaiApiKey: 'test-key', openaiModel: 'gpt-4', fetch }
    await handle(SOURCE_EXAMPLE as unknown as GitHubPullRequestPayload, config)
    expect(calls).toHaveLength(1)
  })

  it('throws on missing action', async () => {
    const payload = { ...SOURCE_EXAMPLE, action: 'closed' }
    const config: ConnectorConfig = { openaiApiKey: 'test-key', fetch: vi.fn() }
    await expect(handle(payload as unknown as GitHubPullRequestPayload, config)).rejects.toThrow('Expected action "opened"')
  })

  it('throws on missing pull_request.title', async () => {
    const payload = { ...SOURCE_EXAMPLE, pull_request: { ...SOURCE_EXAMPLE.pull_request, title: '' } }
    const config: ConnectorConfig = { openaiApiKey: 'test-key', fetch: vi.fn() }
    await expect(handle(payload as unknown as GitHubPullRequestPayload, config)).rejects.toThrow('pull_request.title is required')
  })

  it('throws on missing pull_request.body', async () => {
    const payload = { ...SOURCE_EXAMPLE, pull_request: { ...SOURCE_EXAMPLE.pull_request, body: undefined } }
    const config: ConnectorConfig = { openaiApiKey: 'test-key', fetch: vi.fn() }
    await expect(handle(payload as unknown as GitHubPullRequestPayload, config)).rejects.toThrow('pull_request.body is required')
  })

  it('throws on missing pull_request.user.login', async () => {
    const payload = { ...SOURCE_EXAMPLE, pull_request: { ...SOURCE_EXAMPLE.pull_request, user: {} } }
    const config: ConnectorConfig = { openaiApiKey: 'test-key', fetch: vi.fn() }
    await expect(handle(payload as unknown as GitHubPullRequestPayload, config)).rejects.toThrow('pull_request.user.login is required')
  })

  it('throws on missing pull_request.head.sha', async () => {
    const payload = { ...SOURCE_EXAMPLE, pull_request: { ...SOURCE_EXAMPLE.pull_request, head: {} } }
    const config: ConnectorConfig = { openaiApiKey: 'test-key', fetch: vi.fn() }
    await expect(handle(payload as unknown as GitHubPullRequestPayload, config)).rejects.toThrow('pull_request.head.sha is required')
  })

  it('throws on non-2xx response from OpenAI', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse({ error: 'invalid_api_key' }, 401))
    const config: ConnectorConfig = { openaiApiKey: 'bad-key', fetch }
    await expect(handle(SOURCE_EXAMPLE as unknown as GitHubPullRequestPayload, config)).rejects.toThrow('OpenAI API error: 401 Unauthorized for https://api.openai/v1/chat/completions')
    expect(calls).toHaveLength(1)
  })

  it('throws when OpenAI response missing content', async () => {
    const badResponse = { ...TARGET_ENDPOINTS[0].response, choices: [{ index: 0, message: { role: 'assistant', content: '' }, finish_reason: 'stop' }] }
    const { fetch, calls } = fakeFetch(() => jsonResponse(badResponse))
    const config: ConnectorConfig = { openaiApiKey: 'test-key', fetch }
    await expect(handle(SOURCE_EXAMPLE as unknown as GitHubPullRequestPayload, config)).rejects.toThrow('OpenAI response missing message content')
    expect(calls).toHaveLength(1)
  })

  it('throws when OpenAI response content is invalid JSON', async () => {
    const badResponse = { ...TARGET_ENDPOINTS[0].response, choices: [{ index: 0, message: { role: 'assistant', content: 'not json' }, finish_reason: 'stop' }] }
    const { fetch, calls } = fakeFetch(() => jsonResponse(badResponse))
    const config: ConnectorConfig = { openaiApiKey: 'test-key', fetch }
    await expect(handle(SOURCE_EXAMPLE as unknown as GitHubPullRequestPayload, config)).rejects.toThrow('Failed to parse OpenAI response content')
    expect(calls).toHaveLength(1)
  })

  it('returns parsed analysis with correct types', async () => {
    const { fetch, calls } = fakeFetch(() => jsonResponse(TARGET_ENDPOINTS[0].response))
    const config: ConnectorConfig = { openaiApiKey: 'test-key', fetch }
    const result = await handle(SOURCE_EXAMPLE as unknown as GitHubPullRequestPayload, config)

    expect(typeof result.analysis.summary).toBe('string')
    expect(Array.isArray(result.analysis.risks)).toBe(true)
    expect(Array.isArray(result.analysis.suggestedReviewers)).toBe(true)
    expect(result.analysis.risks.every(r => typeof r === 'string')).toBe(true)
    expect(result.analysis.suggestedReviewers.every(r => typeof r === 'string')).toBe(true)
    expect(calls).toHaveLength(1)
  })
})

