function parseAnalysis(content: string): PRAnalysis {
  try {
    const parsed = JSON.parse(content) as PRAnalysis
    if (
      typeof parsed.summary !== 'string' ||
      !Array.isArray(parsed.risks) ||
      !Array.isArray(parsed.suggestedReviewers)
    ) {
      throw new Error('Invalid analysis structure')
    }
    return parsed
  } catch (e) {
    throw new Error(`Failed to parse OpenAI response content: ${e instanceof Error ? e.message : String(e)}`)
  }
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const pr = payload as GitHubPullRequestPayload

  const prompt = buildPrompt(pr.pull_request)
  const model = config.openaiModel ?? DEFAULT_MODEL
  const fetchFn = config.fetch ?? fetch

  const openaiResponse = await callOpenAI(config.openaiApiKey, model, prompt, fetchFn)

  const content = openaiResponse.choices[0]?.message?.content
  if (!content) {
    throw new Error('OpenAI response missing message content')
  }

  const analysis = parseAnalysis(content)

  return {
    openaiResponseId: openaiResponse.id,
    analysis
  }
}

