const OPENAI_URL = 'https://api.openai/v1/chat/completions'
const DEFAULT_MODEL = 'gpt-4o-mini'

const RESPONSE_SCHEMA = {
  type: 'json_schema',
  json_schema: {
    name: 'pr_analysis',
    strict: true,
    schema: {
      type: 'object',
      properties: {
        summary: { type: 'string' },
        risks: { type: 'array', items: { type: 'string' } },
        suggestedReviewers: { type: 'array', items: { type: 'string' } }
      },
      required: ['summary', 'risks', 'suggestedReviewers'],
      additionalProperties: false
    }
  }
}

function validatePayload(payload: unknown): asserts payload is GitHubPullRequestPayload {
  if (!payload || typeof payload !== 'object') {
    throw new Error('Payload must be an object')
  }
  const p = payload as Record<string, unknown>
  if (p.action !== 'opened') {
    throw new Error(`Expected action "opened", got "${p.action}"`)
  }
  if (!p.pull_request || typeof p.pull_request !== 'object') {
    throw new Error('Missing pull_request object')
  }
  const pr = p.pull_request as Record<string, unknown>
  if (typeof pr.title !== 'string' || !pr.title.trim()) {
    throw new Error('pull_request.title is required and must be a non-empty string')
  }
  if (typeof pr.body !== 'string') {
    throw new Error('pull_request.body is required and must be a string')
  }
  if (!pr.user || typeof pr.user !== 'object' || typeof (pr.user as Record<string, unknown>).login !== 'string') {
    throw new Error('pull_request.user.login is required and must be a string')
  }
  if (!pr.head || typeof pr.head !== 'object' || typeof (pr.head as Record<string, unknown>).sha !== 'string') {
    throw new Error('pull_request.head.sha is required and must be a string')
  }
}

function buildPrompt(pr: GitHubPullRequestPayload['pull_request']): string {
  return `Analyze this pull request:\n\nTitle: ${pr.title}\n\nBody: ${pr.body}\n\nAuthor: ${pr.user.login}\n\nCommit SHA: ${pr.head.sha}\n\nProvide a structured analysis with summary, risks, and suggested reviewers.`
}

async function callOpenAI(
  apiKey: string,
  model: string,
  prompt: string,
  fetchFn: typeof fetch
): Promise<OpenAIResponse> {
  const body = {
    model,
    messages: [{ role: 'user' as const, content: prompt }],
    response_format: RESPONSE_SCHEMA
  }

  const response = await fetchFn(OPENAI_URL, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${apiKey}`,
      'Content-Type': 'application/json'
    },
    body: JSON.stringify(body)
  })

  if (!response.ok) {
    throw new Error(`OpenAI API error: ${response.status} ${response.statusText} for ${OPENAI_URL}`)
  }

  return response.json() as Promise<OpenAIResponse>
}

function parseAnalysis(content: string): PRAnalysis {
  try {
    const parsed = JSON.parse(content) as PRAnalysis
    if (
      typeof parsed.summary !== 'string' ||
      !Array.isArray(parsed.risks) ||
      !Array.isArray(parsed.suggestedReviewers)
    ) {
      throw new Error('Invalid analysis structure')
    }
    return parsed
  } catch (e) {
    throw new Error(`Failed to parse OpenAI response content: ${e instanceof Error ? e.message : String(e)}`)
  }
}

export async function handle(
  payload: unknown,
  config: ConnectorConfig
): Promise<HandleResult> {
  validatePayload(payload)
  const pr = payload as GitHubPullRequestPayload

  const prompt = buildPrompt(pr.pull_request)
  const model = config.openaiModel ?? DEFAULT_MODEL
  const fetchFn = config.fetch ?? fetch

  const openaiResponse = await callOpenAI(config.openaiApiKey, model, prompt, fetchFn)

  const content = openaiResponse.choices[0]?.message?.content
  if (!content) {
    throw new Error('OpenAI response missing message content')
  }

  const analysis = parseAnalysis(content)

  return {
    openaiResponseId: openaiResponse.id,
    analysis
  }
}

